export function buildMandarinPinyinKeyFromFolded(value) {
  const output = [];
  let sawHan = false;
  for (const character of String(value ?? '').normalize('NFKC').toLocaleLowerCase('ja')) {
    const reading = pinyinByCharacter.get(character);
    if (reading) {
      sawHan = true;
      output.push(reading);
    } else if (HAN_CHARACTER.test(character)) {
      return '';
    } else if (/^[a-z0-9]$/u.test(character)) {
      output.push(character);
    }
  }
  return sawHan ? output.join('') : '';
}
